SELECT ?year (COUNT(DISTINCT ?seat) AS ?numberOfSeats) WHERE {
  {
    SELECT DISTINCT ?seat ?year WHERE {
      ?person p:P39 ?stmt1, ?stmt2 .
      ?stmt1 ps:P39 ?seat ;
             pq:P580 ?start1 .
      ?stmt2 ps:P39 ?otherSeat ;
             pq:P580 ?start2 .
      ?seat wdt:P31 wd:Q4164871 .
      ?otherSeat wdt:P31 wd:Q4164871 .
      FILTER(?seat != ?otherSeat)
      FILTER(YEAR(?start1) >= 1830 && YEAR(?start1) <= 1910)
      FILTER(YEAR(?start2) >= 1830 && YEAR(?start2) <= 1910)
      BIND(YEAR(?start2) AS ?year)
      FILTER(?start2 > ?start1)
    }
  }
  FILTER(?year >= 1830 && ?year <= 1910)
  ?seat wdt:P361 wd:Q11005 .
}
GROUP BY ?year
ORDER BY ?year

