  VALUES ?position { wd:Q33999 wd:Q177220 }

  ?actor wdt:P31 wd:Q5 ;
         wdt:P21 ?male ;
         wdt:P106 wd:Q33999 .

  ?movie1 p:P161 ?cast1 .
  ?cast1 ps:P161 ?actor ;
         pq:P453 ?character ;
         pq:P1545 ?ord1 .

  ?movie2 p:P161 ?cast2 .
  ?cast2 ps:P161 ?actor ;
         pq:P453 ?character ;
         pq:P1545 ?ord2 .

  ?movie3 p:P161 ?cast3 .
  ?cast3 ps:P161 ?actor ;
         pq:P453 ?character ;
         pq:P1545 ?ord3 .

  FILTER(?movie1 != ?movie2 && ?movie2 != ?movie3 && ?movie1 != ?movie3)

  ?movie1 wdt:P31 wd:Q11424 ; wdt:P577 ?date1 .
  ?movie2 wdt:P31 wd:Q11424 ; wdt:P577 ?date2 .
  ?movie3 wdt:P31 wd:Q11424 ; wdt:P577 ?date3 .

  FILTER(?date1 < ?date2 && ?date2 < ?date3)
  FILTER((YEAR(?date3) - YEAR(?date1)) >= 20)

  {
    ?movie1 wdt:P179 ?series .
    ?movie2 wdt:P179 ?series .
    ?movie3 wdt:P179 ?series .
  }
  UNION
  {
    ?series p:P527 ?part1, ?part2, ?part3 .
    ?part1 ps:P527 ?movie1 ; pq:P1545 "1" .
    ?part2 ps:P527 ?movie2 ; pq:P1545 "2" .
    ?part3 ps:P527 ?movie3 ; pq:P1545 "3" .
  }

  FILTER NOT EXISTS {
    ?movieX p:P161 ?castX .
    ?castX ps:P161 ?actor ;
           pq:P453 ?character .
    ?movieX wdt:P179 ?series ;
           wdt:P577 ?dateX .
    FILTER(?dateX > ?date1 && ?dateX < ?date3 && ?movieX != ?movie1 && ?movieX != ?movie2 && ?movieX != ?movie3)
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?actorLabel ?characterLabel ?date1

