SELECT ?award ?awardLabel ?femaleCount ?totalCount ?percentage WHERE {
  {
    SELECT ?award (COUNT(DISTINCT ?female) AS ?femaleCount) (COUNT(DISTINCT ?recipient) AS ?totalCount)
           ((100.0 * COUNT(DISTINCT ?female)) / COUNT(DISTINCT ?recipient) AS ?percentage)
    WHERE {
      ?recipient wdt:P166 ?award ;
                 wdt:P21 ?gender .
      FILTER(?gender IN (wd:Q6581072, wd:Q1052281))
      BIND(IF(?gender = wd:Q6581072, ?recipient, UNDEF) AS ?female)
    }
    GROUP BY ?award
    HAVING(COUNT(DISTINCT ?recipient) > 0)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?percentage) DESC(?femaleCount) DESC(?totalCount) ?awardLabel

