SELECT DISTINCT ?capital1 ?capital1Label ?country1 ?country1Label ?capital2 ?capital2Label ?country2 ?country2Label ?distance WHERE {
  ?country1 wdt:P31 wd:Q3624078 ;
            wdt:P36 ?capital1 .
  ?country2 wdt:P31 wd:Q3624078 ;
            wdt:P36 ?capital2 .
  FILTER(?country1 != ?country2)
  FILTER(STR(?country1) < STR(?country2))
  FILTER NOT EXISTS { ?country1 wdt:P47 ?country2 }
  FILTER NOT EXISTS { ?country2 wdt:P47 ?country1 }
  ?capital1 wdt:P625 ?coord1 .
  ?capital2 wdt:P625 ?coord2 .
  BIND(geof:distance(?coord1, ?coord2) AS ?distance)
  FILTER(?distance < 200)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?distance

