SELECT ?occupation ?occupationLabel ?femaleCount ?maleCount ?totalCount ?femaleShare ?maleShare WHERE {
  {
    SELECT ?occupation
           (SUM(?f) AS ?femaleCount)
           (SUM(?m) AS ?maleCount)
           ((SUM(?f) + SUM(?m)) AS ?totalCount)
           (SUM(?f) / (SUM(?f) + SUM(?m)) AS ?femaleShare)
           (SUM(?m) / (SUM(?f) + SUM(?m)) AS ?maleShare)
    WHERE {
      ?item p:P1087 ?statement .
      ?statement ps:P1087 ?count ;
                 pq:P585 ?date ;
                 pq:P17 wd:Q30 ;
                 pq:P21 ?gender ;
                 pq:P1013 ?occupation .
      FILTER(?gender IN (wd:Q6581072, wd:Q6581097))
      BIND(IF(?gender = wd:Q6581072, ?count, 0) AS ?f)
      BIND(IF(?gender = wd:Q6581097, ?count, 0) AS ?m)
    }
    GROUP BY ?occupation
    HAVING((SUM(?f) + SUM(?m)) > 1000)
    ORDER BY ASC(IF((SUM(?f) / (SUM(?f) + SUM(?m))) < (SUM(?m) / (SUM(?f) + SUM(?m))),
                    (SUM(?f) / (SUM(?f) + SUM(?m))),
                    (SUM(?m) / (SUM(?f) + SUM(?m)))))
    LIMIT 50
  }
  {
    SELECT ?occupation
           (SUM(?f2) AS ?femaleCount)
           (SUM(?m2) AS ?maleCount)
           ((SUM(?f2) + SUM(?m2)) AS ?totalCount)
           (SUM(?f2) / (SUM(?f2) + SUM(?m2)) AS ?femaleShare)
           (SUM(?m2) / (SUM(?f2) + SUM(?m2)) AS ?maleShare)
    WHERE {
      ?item2 p:P1087 ?statement2 .
      ?statement2 ps:P1087 ?count2 ;
                  pq:P585 ?date2 ;
                  pq:P17 wd:Q30 ;
                  pq:P21 ?gender2 ;
                  pq:P1013 ?occupation .
      FILTER(?gender2 IN (wd:Q6581072, wd:Q6581097))
      BIND(IF(?gender2 = wd:Q6581072, ?count2, 0) AS ?f2)
      BIND(IF(?gender2 = wd:Q6581097, ?count2, 0) AS ?m2)
    }
    GROUP BY ?occupation
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ASC(IF(?femaleShare < ?maleShare, ?femaleShare, ?maleShare))

