SELECT DISTINCT ?institution ?institutionLabel WHERE {
  {
    SELECT ?institution (COUNT(DISTINCT ?conference) AS ?instCount) WHERE {
      ?conference wdt:P31 wd:Q2020153 ;
                  rdfs:label ?confLabel .
      FILTER(LANG(?confLabel) = "en")
      FILTER(CONTAINS(LCASE(?confLabel), "#vbib"))

      ?conference (wdt:P664|wdt:P859|wdt:P710|wdt:P463) ?institution .
    }
    GROUP BY ?institution
  }
  {
    SELECT (COUNT(DISTINCT ?conference) AS ?totalCount) WHERE {
      ?conference wdt:P31 wd:Q2020153 ;
                  rdfs:label ?confLabel .
      FILTER(LANG(?confLabel) = "en")
      FILTER(CONTAINS(LCASE(?confLabel), "#vbib"))
    }
  }
  FILTER(?instCount = ?totalCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY ?institutionLabel

