  ?minister wdt:P27 wd:Q38 .

  ?cabinet wdt:P31 wd:Q640506 ;
           wdt:P571 ?startDate .
  FILTER(?startDate >= "1990-01-01T00:00:00Z"^^xsd:dateTime)

  {
    SELECT ?minister WHERE {
      ?minister p:P39 ?st1, ?st2 .
      ?st1 ps:P39 ?pos1 ; pq:P2937 ?cab1 .
      ?st2 ps:P39 ?pos2 ; pq:P2937 ?cab2 .
      ?pos1 wdt:P279* wd:Q83307 .
      ?pos2 wdt:P279* wd:Q83307 .
      ?minister wdt:P27 wd:Q38 .
      ?cab1 wdt:P31 wd:Q640506 ; wdt:P571 ?d1 .
      ?cab2 wdt:P31 wd:Q640506 ; wdt:P571 ?d2 .
      FILTER(?d1 >= "1990-01-01T00:00:00Z"^^xsd:dateTime)
      FILTER(?d2 >= "1990-01-01T00:00:00Z"^^xsd:dateTime)
      FILTER(?cab1 != ?cab2)
    }
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,it". }
}
ORDER BY ?ministerLabel ?cabinetLabel

