SELECT ?country ?countryLabel ?day ?dayLabel (COUNT(?election) AS ?electionCount) WHERE {
  ?election wdt:P31/wdt:P279* wd:Q40231 ;
            wdt:P17 ?country ;
            wdt:P585 ?date .
  BIND(WEEKDAY(?date) AS ?weekdayNum)
  VALUES (?weekdayNum ?day) {
    (0 wd:Q131723) 
    (1 wd:Q131722) 
    (2 wd:Q131724) 
    (3 wd:Q131725) 
    (4 wd:Q131726) 
    (5 wd:Q131727) 
    (6 wd:Q131728)
  }
  {
    SELECT ?country (MAX(?count) AS ?maxCount) WHERE {
      {
        SELECT ?country ?weekdayNum (COUNT(?election) AS ?count) WHERE {
          ?election wdt:P31/wdt:P279* wd:Q40231 ;
                    wdt:P17 ?country ;
                    wdt:P585 ?date .
          BIND(WEEKDAY(?date) AS ?weekdayNum)
        }
        GROUP BY ?country ?weekdayNum
      }
    }
    GROUP BY ?country
  }
  {
    SELECT ?country ?weekdayNum (COUNT(?election) AS ?electionCount) WHERE {
      ?election wdt:P31/wdt:P279* wd:Q40231 ;
                wdt:P17 ?country ;
                wdt:P585 ?date .
      BIND(WEEKDAY(?date) AS ?weekdayNum)
    }
    GROUP BY ?country ?weekdayNum
  }
  FILTER(?electionCount = ?maxCount)
  FILTER(?weekdayNum = WEEKDAY(?date))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel ?day ?dayLabel ?electionCount
ORDER BY DESC(?electionCount) ?countryLabel

