SELECT DISTINCT ?person ?personLabel ?grave ?graveLabel ?deathDate ?image WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P119 wd:Q311 ;
          wdt:P570 ?deathDate .
  FILTER(?deathDate >= "1800-01-01T00:00:00Z"^^xsd:dateTime && ?deathDate < "1850-01-01T00:00:00Z"^^xsd:dateTime)
  OPTIONAL { ?person wdt:P1442 ?grave . }
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
