SELECT DISTINCT ?person ?personLabel ?birthDate ?age WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P27 wd:Q38 ;
          wdt:P106 wd:Q82955 ;
          wdt:P569 ?birthDate ;
          p:P39 ?statement .
  ?statement ps:P39 ?position .
  ?position wdt:P279* wd:Q83307 .

  BIND(YEAR(NOW()) - YEAR(?birthDate) - IF((MONTH(NOW()) < MONTH(?birthDate)) || ((MONTH(NOW()) = MONTH(?birthDate)) && (DAY(NOW()) < DAY(?birthDate))), 1, 0) AS ?age)

  FILTER(?age >= 50 && ?age <= 80)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

