SELECT ?taxon ?taxonLabel WHERE {
  VALUES ?species { wd:Q15525185 wd:Q1735170 }
  ?species wdt:P171* ?taxon .
  FILTER NOT EXISTS {
    VALUES ?species2 { wd:Q15525185 wd:Q1735170 }
    FILTER(?species2 != ?species)
    ?species2 wdt:P171* ?taxon .
  }
  FILTER NOT EXISTS {
    ?species wdt:P171* ?moreSpecific .
    ?moreSpecific wdt:P171+ ?taxon .
    FILTER NOT EXISTS {
      VALUES ?species3 { wd:Q15525185 wd:Q1735170 }
      ?species3 wdt:P171* ?moreSpecific .
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} LIMIT 1

