SELECT ?person ?personLabel ?start ?end ?duration WHERE {
  {
    SELECT ?person ?start ?end ((?endOrNow - ?start) AS ?duration) WHERE {
      ?person p:P6 ?statement .
      ?statement ps:P6 ?office ;
                 pq:P17 wd:Q142 ;
                 pq:P580 ?start .
      FILTER(?office = wd:Q14211)
      OPTIONAL { ?statement pq:P582 ?end . }
      BIND(COALESCE(?end, NOW()) AS ?endOrNow)
    }
    ORDER BY DESC(?duration)
    LIMIT 10
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?duration)

