SELECT DISTINCT ?date ?eventLabel WHERE {
  VALUES ?person { wd:Q9711 }
  {
    ?person wdt:P569 ?date .
    BIND("date of birth"@en AS ?eventLabel)
  }
  UNION
  {
    ?person wdt:P570 ?date .
    BIND("date of death"@en AS ?eventLabel)
  }
  UNION
  {
    ?person wdt:P119 ?placeOfBurial .
    ?person p:P119 ?burialStatement .
    ?burialStatement ps:P119 ?placeOfBurial ;
                     pq:P585 ?date .
    BIND("burial date"@en AS ?eventLabel)
  }
}
ORDER BY ?date

