SELECT ?decade ?placeOfBirth ?placeOfBirthLabel (COUNT(DISTINCT ?person) AS ?winnerCount) WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P166 ?nobelPrize ;
          wdt:P569 ?birthDate ;
          wdt:P19 ?placeOfBirth .
  ?nobelPrize wdt:P31 wd:Q7191 .
  BIND(YEAR(?birthDate) AS ?year)
  BIND(CONCAT(STR(FLOOR(?year / 10) * 10), "s") AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?decade ?placeOfBirth ?placeOfBirthLabel
ORDER BY ?decade DESC(?winnerCount)
